head.script:
// Facebook Pixel - Conditional loading for performance
function loadFacebookPixel() {
  if (window.fbPixelLoaded) return
  window.fbPixelLoaded = true

  !function (f, b, e, v, n, t, s) {
    if (f.fbq) return; n = f.fbq = function () {
      n.callMethod ?
        n.callMethod.apply(n, arguments) : n.queue.push(arguments)
    }
    if (!f._fbq) f._fbq = n; n.push = n; n.loaded = !0; n.version = '2.0'
    n.queue = []; t = b.createElement(e); t.async = !0
    t.src = v; s = b.getElementsByTagName(e)[0]
    s.parentNode.insertBefore(t, s)
  }(window, document, 'script',
    'https://connect.facebook.net/en_US/fbevents.js')
  fbq('init', '1265199675399549')
  fbq('track', 'PageView')
}

// Only load Facebook Pixel in production
if (window.location.hostname !== 'localhost') {
  // Load Facebook Pixel on user interaction or after 5 seconds
  const fbEvents = ['click', 'scroll', 'touchstart']
  const loadFBOnInteraction = () => {
    loadFacebookPixel()
    fbEvents.forEach(event => document.removeEventListener(event, loadFBOnInteraction))
  }

  fbEvents.forEach(event => document.addEventListener(event, loadFBOnInteraction))
  setTimeout(loadFacebookPixel, 5000) // Fallback after 5 seconds
}

