body.script:
(function () {
  // ===== Config =====
  var PHONE_E164 = "551151989668" // só dígitos com DDI
  var MENSAGEM = "Olá! Gostaria de saber mais sobre o HyperGestor."
  var UTM = "utm_source=site&utm_medium=whatsapp_fab&utm_campaign=contato"
  var OPEN_IN_NEW = true // abrir em nova aba

  // ===== Helpers =====
  function onlyDigits(s) { return String(s).replace(/\D+/g, '') }
  function enc(s) { return encodeURIComponent(s) }
  function waMeUrl(phone, text) {
    var p = onlyDigits(phone)
    var url = "https://wa.me/" + p + "?text=" + enc(text)
    if (UTM) url += "&" + UTM
    return url
  }
  function abrir(url) { OPEN_IN_NEW ? window.open(url, "_blank", "noopener") : (window.location.href = url) }

  // GA4 -> envia evento e só então abre (com fallback)
  function trackThenOpen(url) {
    var abriu = false
    function go() { if (!abriu) { abriu = true; abrir(url) } }

    if (typeof window.gtag === "function") {
      try {
        window.gtag("event", "clique_whatsapp", {
          method: "whatsapp_fab",
          event_label: url,
          transport_type: "beacon",
          event_callback: go
        })
        setTimeout(go, 700) // fallback
      } catch (e) { go() }
    } else { go() }
  }

  // ===== Bind =====
  var fab = document.getElementById("wpp-fab")
  var destino = waMeUrl(PHONE_E164, MENSAGEM)

  // Hide WhatsApp button on Painel page
  function checkAndHideOnPainel() {
    var currentPath = window.location.pathname
    if (currentPath === '/painel' || currentPath.endsWith('/painel') || currentPath.includes('/painel')) {
      fab.style.display = 'none'
    } else {
      fab.style.display = 'grid'
    }
  }

  // Check on load
  checkAndHideOnPainel()

  // Check on route changes (for SPA navigation)
  window.addEventListener('popstate', checkAndHideOnPainel)

  // For React Router, also listen to any hash/path changes
  var _pushState = history.pushState
  var _replaceState = history.replaceState
  history.pushState = function () {
    _pushState.apply(history, arguments)
    checkAndHideOnPainel()
  }
  history.replaceState = function () {
    _replaceState.apply(history, arguments)
    checkAndHideOnPainel()
  }

  fab.addEventListener("click", function () { trackThenOpen(destino) })
  fab.addEventListener("keydown", function (e) {
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); trackThenOpen(destino) }
  })
})();

    (function() {
      var contentPrivacy = '
Política de Privacidade — Hyper Gestor
Última atualização: 30 de março de 2026
O Hyper Gestor, operado por Hyper Gestor Tecnologia Ltda., inscrita no CNPJ sob nº 51.641.289/0001-69, com sede em Vinhedo/SP, está comprometido com a proteção dos dados pessoais e a privacidade de seus usuários.
Esta Política de Privacidade descreve como os dados são coletados, utilizados, armazenados e protegidos no uso da plataforma.

1. Natureza do Serviço
O Hyper Gestor é uma plataforma de CRM multiempresa, disponível via web e aplicativos móveis (Android e iOS), com recursos de Gestão de clientes e leads, Automação de atendimento, Integração com canais de comunicação e Uso de Inteligência Artificial para interação, análise e automação comercial. O sistema é destinado exclusivamente a empresas (B2B).

2. Dados Coletados
O Hyper Gestor poderá coletar e tratar os seguintes dados: 2.1 Dados Cadastrais (Nome, e-mail, telefone, CNPJ, endereço); 2.2 Dados Operacionais (Leads, histórico de atendimentos); 2.3 Dados Técnicos (IP, logs); 2.4 Dados Sensíveis Operacionais (Áudios, imagens, localização autorizada).

3. Uso de Inteligência Artificial
Utilizamos tecnologias de IA (incluindo OpenAI) para automatizar interações, sugerir respostas, classificar leads e processar voz. Importante: As interações podem ser processadas por provedores externos; dados não são comercializados; o uso envolve decisões automatizadas.

4. Finalidade
Operação da plataforma, gestão de relacionamento, automação comercial, melhoria da experiência, segurança e cumprimento de obrigações legais.

5. Integrações
Meta Platforms (WhatsApp Business), serviços de mensageria e sistemas de concessionárias, mediante configuração do cliente.

6. Direitos e Segurança
Não comercializamos dados. Adotamos criptografia, logs de auditoria e backups (LGPD). Solicitações: dpo@hypergestor.com.br';

      var contentTerms = '
Termo de Uso — Hyper Gestor
Última atualização: 30 de março de 2026
Este Termo regula o acesso e utilização da plataforma Hyper Gestor, operada pela Hyper Gestor Tecnologia Ltda. (CNPJ 51.641.289/0001-69), com sede em Vinhedo/SP.

1. Objeto e Elegibilidade
Plataforma CRM multiempresa (B2B) para gestão de vendas e automação. O usuário declara possuir poderes para representar a empresa contratante.

2. Uso da Plataforma
O usuário deve fornecer informações verdadeiras, manter sigilo das credenciais e não realizar engenharia reversa ou uso ilícito.

3. Inteligência Artificial
Utilizamos IA (OpenAI) para automação. O usuário reconhece que as respostas podem conter imprecisões e é responsável pelas decisões tomadas com base nas sugestões da IA.

4. Integrações e Propriedade
Integrações com WhatsApp/Meta seguem termos dos fornecedores. Todos os direitos de código e marca pertencem exclusivamente ao Hyper Gestor.

5. Responsabilidade e Foro
O Hyper Gestor não se responsabiliza por decisões comerciais ou falhas de terceiros. Fica eleito o foro de Vinhedo/SP para dirimir controvérsias. Contato: dpo@hypergestor.com.br';

      function checkRoute() {
        var path = window.location.pathname;
        var overlay = document.getElementById('universal-legal-overlay');
        var root = document.getElementById('root');
        var target = document.getElementById('legal-content-target');
        var fab = document.getElementById('wpp-fab');

        if (path.includes('privacy-policy') || path.includes('terms-of-use')) {
          var isPrivacy = path.includes('privacy-policy');
          target.innerHTML = '← Voltar para o Início' + 
                             '
' +
                             (isPrivacy ? contentPrivacy : contentTerms) +
                             '© 2026 HyperGestor';

          if (root) root.style.display = 'none';
          if (fab) fab.style.display = 'none';
          overlay.style.display = 'block';
          document.title = (isPrivacy ? "Política de Privacidade" : "Termos de Uso") + " | HyperGestor";
          window.scrollTo(0,0);
        } else {
          overlay.style.display = 'none';
          if (root) root.style.display = 'block';
          // wpp-fab logic is already handled by its own script
        }
      }

      window.addEventListener('popstate', checkRoute);
      // Listen for hash changes if needed for local testing
      window.addEventListener('hashchange', checkRoute);

      // Patch pushState to detect internal navigation
      var originalPush = history.pushState;
      history.pushState = function() {
        originalPush.apply(history, arguments);
        checkRoute();
      };

      // Run once on load
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', checkRoute);
      } else {
        checkRoute();
      }
    })();
